CREATE OR REPLACE FUNCTION private.guard_engagement_request_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_status text;
begin
  select a.status into v_status from public.job_applications a
    where a.application_id=new.application_id for update;
  if not found or v_status is distinct from 'hired' then
    raise exception 'Assignment Requests require a hired Application.';
  end if;
  if exists(select 1 from public.job_engagement_closures c where c.application_id=new.application_id) then
    raise exception 'This Job Engagement is closed; no new Shift may be reserved.';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.lock_engagement_dispute_application()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_application_id uuid;
begin
  if new.application_id is not null then
    v_application_id:=new.application_id;
  elsif new.assignment_id is not null then
    select a.application_id into v_application_id from public.work_assignments a where a.assignment_id=new.assignment_id;
  end if;
  if v_application_id is null then raise exception 'Related Job Application not found for Dispute.'; end if;
  perform 1 from public.job_applications a where a.application_id=v_application_id for update;
  if not found then raise exception 'Related Job Application not found for Dispute.'; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.protect_assignment_request_terminal_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.cancelled_at is not null and new is distinct from old then
    raise exception 'Cancelled Assignment Requests are immutable.';
  end if;
  if old.assignment_id is not null and new.assignment_id is distinct from old.assignment_id then
    raise exception 'A created Assignment Request cannot be relinked.';
  end if;
  if new.cancelled_at is not null and old.cancelled_at is null and new.assignment_id is not null then
    raise exception 'An Assignment Request with a created Shift cannot be cancelled.';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.record_job_engagement_closure(p_application_id uuid, p_actor_id uuid, p_reason text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_app public.job_applications%rowtype; v_company_id uuid; v_closed_at timestamptz;
begin
  select * into v_app from public.job_applications a
    where a.application_id=p_application_id for update;
  if not found then raise exception 'Job Application not found.'; end if;
  if v_app.status is distinct from 'hired' then raise exception 'Only a hired Job Application can be closed.'; end if;
  select j.company_id into v_company_id from public.job_postings j where j.job_id=v_app.job_id;
  if v_company_id is null or public.can_manage_company_jobs(v_company_id) is not true then
    raise exception 'Current Company Representative authorization is required.' using errcode='42501';
  end if;
  if exists(select 1 from public.job_engagement_closures c where c.application_id=p_application_id) then
    raise exception 'This Job Engagement is already closed.';
  end if;
  if not exists(select 1 from public.work_assignments a where a.application_id=p_application_id
      and a.status='completed' and a.verification_status='verified' and a.verified_at is not null) then
    raise exception 'At least one completed and verified Shift is required.';
  end if;
  if exists(select 1 from public.work_assignments a where a.application_id=p_application_id
      and not ((a.status='completed' and a.verification_status='verified' and a.verified_at is not null)
        or (a.status='cancelled' and exists(select 1 from public.work_assignment_cancellations x
             where x.assignment_id=a.assignment_id)))) then
    raise exception 'Every Shift must be completed and verified, or have an audited cancellation.';
  end if;
  if exists(select 1 from public.work_assignment_creation_requests r
      where r.application_id=p_application_id and r.assignment_id is null and r.cancelled_at is null) then
    raise exception 'An unresolved Shift reservation must be created or cancelled before closure.';
  end if;
  if exists(select 1 from public.disputes d where d.status in ('open','investigating','pending_information')
      and (d.application_id=p_application_id or d.assignment_id in (
        select a.assignment_id from public.work_assignments a where a.application_id=p_application_id))) then
    raise exception 'An unresolved related Dispute blocks Job Engagement closure.';
  end if;
  if p_reason is null or p_reason !~ '[^[:space:]]' or char_length(p_reason)>2000 then
    raise exception 'A closure reason of 1 to 2000 characters is required.';
  end if;
  insert into public.job_engagement_closures(application_id,closed_by,closure_reason)
    values(p_application_id,p_actor_id,btrim(p_reason)) returning closed_at into v_closed_at;
  update public.job_engagement_closure_requests r
    set status='accepted',processed_by=p_actor_id,processed_at=v_closed_at,
        response_reason='Engagement closed: '||btrim(p_reason)
    where r.application_id=p_application_id and r.status='pending';
  insert into public.job_engagement_closure_request_events(request_id,actor_id,action,reason)
    select r.request_id,p_actor_id,'closed_by_company',btrim(p_reason)
    from public.job_engagement_closure_requests r
    where r.application_id=p_application_id and r.status='accepted' and r.processed_at=v_closed_at;
  return v_closed_at;
end
$function$

CREATE OR REPLACE FUNCTION public.cancel_scheduled_work_assignment(p_assignment_id uuid, p_reason text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_app_id uuid; v_company_id uuid; v_status text; v_verified text; v_cancelled_at timestamptz;
begin
  if auth.uid() is null then raise exception 'Authentication required.' using errcode='28000'; end if;
  if p_reason is null or p_reason !~ '[^[:space:]]' or char_length(p_reason)>2000 then
    raise exception 'A cancellation reason of 1 to 2000 characters is required.';
  end if;
  select a.application_id into v_app_id from public.work_assignments a where a.assignment_id=p_assignment_id;
  if not found then raise exception 'Assignment not found.'; end if;
  perform 1 from public.job_applications a where a.application_id=v_app_id for update;
  select a.company_id,a.status,a.verification_status into v_company_id,v_status,v_verified
    from public.work_assignments a where a.assignment_id=p_assignment_id for update;
  if not found then raise exception 'Assignment not found.'; end if;
  if public.can_manage_company_jobs(v_company_id) is not true then
    raise exception 'Current Company Representative authorization is required.' using errcode='42501';
  end if;
  if v_status is distinct from 'scheduled' or v_verified is distinct from 'not_submitted'
     or exists(select 1 from public.work_attendance a where a.assignment_id=p_assignment_id
       and (a.check_in_at is not null or a.check_out_at is not null))
     or exists(select 1 from public.work_evidence e where e.assignment_id=p_assignment_id) then
    raise exception 'Only an untouched scheduled Shift can be cancelled.';
  end if;
  insert into public.work_assignment_cancellations(assignment_id,cancelled_by,cancellation_reason)
    values(p_assignment_id,auth.uid(),btrim(p_reason)) returning cancelled_at into v_cancelled_at;
  update public.work_assignments set status='cancelled',updated_at=v_cancelled_at
    where assignment_id=p_assignment_id;
  return v_cancelled_at;
end
$function$

CREATE OR REPLACE FUNCTION public.cancel_work_assignment_request(p_request_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_app_id uuid; v_company_id uuid; v_assignment_id uuid; v_cancelled_at timestamptz;
begin
  if auth.uid() is null then raise exception 'Authentication required.' using errcode='28000'; end if;
  if p_reason is null or p_reason !~ '[^[:space:]]' or char_length(p_reason)>2000 then
    raise exception 'A cancellation reason of 1 to 2000 characters is required.';
  end if;
  select r.application_id into v_app_id from public.work_assignment_creation_requests r where r.request_id=p_request_id;
  if not found then raise exception 'Assignment Request not found.'; end if;
  perform 1 from public.job_applications a where a.application_id=v_app_id for update;
  if not found then raise exception 'Job Application not found.'; end if;
  select r.assignment_id,r.cancelled_at,j.company_id into v_assignment_id,v_cancelled_at,v_company_id
  from public.work_assignment_creation_requests r
  join public.job_applications a on a.application_id=r.application_id
  join public.job_postings j on j.job_id=a.job_id
  where r.request_id=p_request_id for update of r;
  if not found then raise exception 'Assignment Request not found.'; end if;
  if public.can_manage_company_jobs(v_company_id) is not true then
    raise exception 'Current Company Representative authorization is required.' using errcode='42501';
  end if;
  if v_assignment_id is not null then raise exception 'A request with a created Assignment cannot be cancelled.'; end if;
  if v_cancelled_at is not null then raise exception 'Assignment Request is already cancelled.'; end if;
  v_cancelled_at:=pg_catalog.clock_timestamp();
  update public.work_assignment_creation_requests set cancelled_by=auth.uid(),cancelled_at=v_cancelled_at,
    cancellation_reason=btrim(p_reason) where request_id=p_request_id;
end
$function$

CREATE OR REPLACE FUNCTION public.check_in_work_assignment(p_assignment_id uuid, p_location_status text, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_assignment record;
    v_check_in_at timestamptz;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'You must be signed in.';
    END IF;

    SELECT
        a.assignment_id,
        a.worker_id,
        a.status,
        a.scheduled_start,
        a.scheduled_end
    INTO v_assignment
    FROM public.work_assignments a
    WHERE a.assignment_id = p_assignment_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Work assignment not found.';
    END IF;

    IF v_assignment.worker_id <> auth.uid()
       OR NOT EXISTS (
           SELECT 1
           FROM public.users u
           WHERE u.user_id = auth.uid()
             AND u.role = 'job_seeker'::public.user_role
             AND u.status = 'active'::public.account_status
       ) THEN
        RAISE EXCEPTION 'You cannot check in to this assignment.';
    END IF;

    IF v_assignment.status <> 'scheduled' THEN
        RAISE EXCEPTION 'This assignment is not available for check-in.';
    END IF;

    IF p_location_status IS NULL
       OR p_location_status NOT IN ('granted', 'denied', 'unavailable') THEN
        RAISE EXCEPTION 'Invalid location permission status.';
    END IF;

    IF p_location_status = 'granted' THEN
        IF p_latitude IS NULL
           OR p_longitude IS NULL
           OR p_latitude NOT BETWEEN -90 AND 90
           OR p_longitude NOT BETWEEN -180 AND 180 THEN
            RAISE EXCEPTION 'Valid coordinates are required when GPS is granted.';
        END IF;
    ELSIF p_latitude IS NOT NULL OR p_longitude IS NOT NULL THEN
        RAISE EXCEPTION 'Coordinates must be omitted when GPS is unavailable.';
    END IF;

    -- Allow check-in from 60 minutes before scheduled start
    -- until the scheduled shift ends.
    IF clock_timestamp() < v_assignment.scheduled_start - interval '60 minutes'
       OR clock_timestamp() > v_assignment.scheduled_end THEN
        RAISE EXCEPTION 'Check-in is outside the allowed shift window.';
    END IF;

    v_check_in_at := clock_timestamp();

    INSERT INTO public.work_attendance (
        assignment_id,
        check_in_at,
        check_in_latitude,
        check_in_longitude,
        check_in_location_status
    )
    VALUES (
        p_assignment_id,
        v_check_in_at,
        p_latitude,
        p_longitude,
        p_location_status
    );

    UPDATE public.work_assignments
    SET status = 'active',
        updated_at = v_check_in_at
    WHERE assignment_id = p_assignment_id;

    RETURN v_check_in_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_out_work_assignment(p_assignment_id uuid, p_location_status text, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_assignment record;
    v_attendance record;
    v_check_out_at timestamptz;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'You must be signed in.';
    END IF;

    SELECT
        a.assignment_id,
        a.worker_id,
        a.status
    INTO v_assignment
    FROM public.work_assignments a
    WHERE a.assignment_id = p_assignment_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Work assignment not found.';
    END IF;

    IF v_assignment.worker_id <> auth.uid()
       OR NOT EXISTS (
           SELECT 1
           FROM public.users u
           WHERE u.user_id = auth.uid()
             AND u.role = 'job_seeker'::public.user_role
             AND u.status = 'active'::public.account_status
       ) THEN
        RAISE EXCEPTION 'You cannot check out of this assignment.';
    END IF;

    IF v_assignment.status <> 'active' THEN
        RAISE EXCEPTION 'This assignment is not active.';
    END IF;

    SELECT check_in_at, check_out_at
    INTO v_attendance
    FROM public.work_attendance
    WHERE assignment_id = p_assignment_id
    FOR UPDATE;

    IF NOT FOUND OR v_attendance.check_in_at IS NULL THEN
        RAISE EXCEPTION 'You must check in before checking out.';
    END IF;

    IF v_attendance.check_out_at IS NOT NULL THEN
        RAISE EXCEPTION 'You have already checked out.';
    END IF;

    IF p_location_status IS NULL
       OR p_location_status NOT IN ('granted', 'denied', 'unavailable') THEN
        RAISE EXCEPTION 'Invalid location permission status.';
    END IF;

    IF p_location_status = 'granted' THEN
        IF p_latitude IS NULL
           OR p_longitude IS NULL
           OR p_latitude NOT BETWEEN -90 AND 90
           OR p_longitude NOT BETWEEN -180 AND 180 THEN
            RAISE EXCEPTION 'Valid GPS coordinates are required.';
        END IF;
    ELSIF p_latitude IS NOT NULL OR p_longitude IS NOT NULL THEN
        RAISE EXCEPTION 'Coordinates must be omitted when GPS is unavailable.';
    END IF;

    v_check_out_at := clock_timestamp();

    IF v_check_out_at < v_attendance.check_in_at THEN
        RAISE EXCEPTION 'Check-out cannot precede check-in.';
    END IF;

    UPDATE public.work_attendance
    SET check_out_at = v_check_out_at,
        check_out_latitude = p_latitude,
        check_out_longitude = p_longitude,
        check_out_location_status = p_location_status,
        updated_at = v_check_out_at
    WHERE assignment_id = p_assignment_id;

    UPDATE public.work_assignments
    SET status = 'awaiting_verification',
        updated_at = v_check_out_at
    WHERE assignment_id = p_assignment_id;

    RETURN v_check_out_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_work_assignment(p_application_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_workplace_location text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_application record;
    v_company_id uuid;
    v_assignment_id uuid;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'You must be signed in.';
    END IF;

    SELECT
        a.application_id,
        a.job_id,
        a.applicant_id,
        a.status,
        j.company_id
    INTO v_application
    FROM public.job_applications a
    JOIN public.job_postings j
      ON j.job_id = a.job_id
    WHERE a.application_id = p_application_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Job application not found.';
    END IF;

    IF v_application.status <> 'hired' THEN
        RAISE EXCEPTION
            'Work assignments can only be created for Hired applications.';
    END IF;

    v_company_id := v_application.company_id;

    IF NOT public.can_manage_company_jobs(v_company_id) THEN
        RAISE EXCEPTION
            'You are not authorized to create assignments for this company.';
    END IF;

    IF p_scheduled_start IS NULL
       OR p_scheduled_end IS NULL
       OR p_scheduled_end <= p_scheduled_start THEN
        RAISE EXCEPTION 'Invalid shift schedule.';
    END IF;

    IF p_workplace_location IS NULL
       OR length(trim(p_workplace_location)) = 0
       OR length(p_workplace_location) > 500 THEN
        RAISE EXCEPTION
            'Enter a workplace location of up to 500 characters.';
    END IF;

    INSERT INTO public.work_assignments (
        application_id,
        job_id,
        worker_id,
        company_id,
        scheduled_start,
        scheduled_end,
        workplace_location,
        created_by
    )
    VALUES (
        v_application.application_id,
        v_application.job_id,
        v_application.applicant_id,
        v_company_id,
        p_scheduled_start,
        p_scheduled_end,
        trim(p_workplace_location),
        auth.uid()
    )
    RETURNING assignment_id INTO v_assignment_id;

    RETURN v_assignment_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_work_assignment_request(p_request_id uuid, p_application_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_workplace_location text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_request public.work_assignment_creation_requests; v_app record; v_assignment uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '28000'; END IF;
 -- Same lock order as reservation and the legacy insert trigger.
 SELECT a.status, j.company_id INTO v_app FROM public.job_applications a
 JOIN public.job_postings j ON j.job_id = a.job_id
 WHERE a.application_id = p_application_id FOR UPDATE OF a, j;
 IF NOT FOUND THEN RAISE EXCEPTION 'Application unavailable.'; END IF;
 IF public.can_manage_company_jobs(v_app.company_id) IS NOT TRUE THEN
  RAISE EXCEPTION 'Employer access denied.' USING ERRCODE = '42501';
 END IF;
 SELECT * INTO v_request FROM public.work_assignment_creation_requests WHERE request_id = p_request_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable.' USING ERRCODE = '22023'; END IF;
 IF v_request.actor_id <> auth.uid() OR v_request.company_id <> v_app.company_id THEN
  RAISE EXCEPTION 'Request access denied.' USING ERRCODE = '42501';
 END IF;
 IF v_request.application_id IS DISTINCT FROM p_application_id
 OR v_request.scheduled_start IS DISTINCT FROM p_scheduled_start
 OR v_request.scheduled_end IS DISTINCT FROM p_scheduled_end
 OR v_request.workplace_location IS DISTINCT FROM trim(p_workplace_location) THEN
  RAISE EXCEPTION 'Request payload cannot change.' USING ERRCODE = '22023';
 END IF;
 IF v_request.assignment_id IS NOT NULL THEN RETURN v_request.assignment_id; END IF;
 IF v_app.status <> 'hired' THEN RAISE EXCEPTION 'Application no longer hired.'; END IF;
 v_assignment := public.create_work_assignment(p_application_id, p_scheduled_start, p_scheduled_end, p_workplace_location);
 UPDATE public.work_assignment_creation_requests SET assignment_id = v_assignment WHERE request_id = p_request_id;
 RETURN v_assignment;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_job_engagement_closure_status(p_application_id uuid)
 RETURNS TABLE(closure_status text, eligible boolean, eligibility_reason text, request_id uuid, requested_at timestamp with time zone, request_reason text, response_reason text, closed_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_application public.job_applications%ROWTYPE;
  v_company_id uuid;
  v_closed_at timestamptz;
  v_request public.job_engagement_closure_requests%ROWTYPE;
  v_reason text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required.' USING errcode='28000';
  END IF;
  SELECT a.* INTO v_application
  FROM public.job_applications a
  WHERE a.application_id=p_application_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job Engagement is unavailable to this account.' USING errcode='42501';
  END IF;
  SELECT j.company_id INTO v_company_id
  FROM public.job_postings j WHERE j.job_id=v_application.job_id;
  IF v_application.applicant_id IS DISTINCT FROM v_actor
     AND public.can_manage_company_jobs(v_company_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Job Engagement is unavailable to this account.' USING errcode='42501';
  END IF;
  IF v_application.status IS DISTINCT FROM 'hired' THEN
    RAISE EXCEPTION 'A hired Job Application is required.';
  END IF;

  SELECT c.closed_at INTO v_closed_at
  FROM public.job_engagement_closures c
  WHERE c.application_id=p_application_id;
  SELECT r.* INTO v_request
  FROM public.job_engagement_closure_requests r
  WHERE r.application_id=p_application_id
  ORDER BY r.requested_at DESC,r.request_id DESC LIMIT 1;

  IF v_closed_at IS NOT NULL THEN
    RETURN QUERY SELECT 'closed'::text,true,NULL::text,v_request.request_id,
      v_request.requested_at,v_request.request_reason,v_request.response_reason,v_closed_at;
    RETURN;
  END IF;
  IF v_request.status='pending' THEN
    RETURN QUERY SELECT 'closure_requested'::text,false,
      'Waiting for the Company to review the Worker request.'::text,
      v_request.request_id,v_request.requested_at,v_request.request_reason,
      v_request.response_reason,NULL::timestamptz;
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.work_assignments a
    WHERE a.application_id=p_application_id AND a.status='completed'
      AND a.verification_status='verified' AND a.verified_at IS NOT NULL
  ) THEN
    v_reason:='At least one completed and verified Shift is required.';
  ELSIF EXISTS (
    SELECT 1 FROM public.work_assignments a
    WHERE a.application_id=p_application_id
      AND NOT (
        (a.status='completed' AND a.verification_status='verified' AND a.verified_at IS NOT NULL)
        OR (a.status='cancelled' AND EXISTS (
          SELECT 1 FROM public.work_assignment_cancellations x
          WHERE x.assignment_id=a.assignment_id
        ))
      )
  ) THEN
    v_reason:='Every Shift must be completed and verified, or have an audited cancellation.';
  ELSIF EXISTS (
    SELECT 1 FROM public.work_assignment_creation_requests r
    WHERE r.application_id=p_application_id AND r.assignment_id IS NULL
      AND r.cancelled_at IS NULL
  ) THEN
    v_reason:='An unresolved Shift reservation must be created or cancelled before closure.';
  ELSIF EXISTS (
    SELECT 1 FROM public.disputes d
    WHERE d.status IN ('open','investigating','pending_information')
      AND (d.application_id=p_application_id OR d.assignment_id IN (
        SELECT a.assignment_id FROM public.work_assignments a
        WHERE a.application_id=p_application_id
      ))
  ) THEN
    v_reason:='An unresolved related Dispute blocks Job Engagement closure.';
  END IF;

  RETURN QUERY SELECT
    CASE WHEN v_reason IS NULL THEN 'open' ELSE 'ineligible' END::text,
    v_reason IS NULL,v_reason,v_request.request_id,v_request.requested_at,
    v_request.request_reason,v_request.response_reason,NULL::timestamptz;
END
$function$

CREATE OR REPLACE FUNCTION public.guard_work_assignment_duplicate_shift()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_claim uuid; v_app_status text; v_locked_app uuid;
begin
  -- Existing trigger also fires for schedule/application relinks. Lock both
  -- application rows in UUID order and reject edits involving a finalized
  -- engagement, including attempts to move a shift out of a closed application.
  if tg_op='UPDATE' then
    for v_locked_app in
      select a.application_id from public.job_applications a
      where a.application_id in (old.application_id,new.application_id)
      order by a.application_id for update
    loop
      if exists(select 1 from public.job_engagement_closures c where c.application_id=v_locked_app) then
        raise exception 'This Job Engagement is closed; its Shifts cannot be changed.';
      end if;
    end loop;
  end if;
  select a.status into v_app_status from public.job_applications a
    where a.application_id=new.application_id for update;
  if not found then raise exception 'Job Application not found.'; end if;
  if v_app_status is distinct from 'hired' then raise exception 'Assignments require a hired Application.'; end if;
  if exists(select 1 from public.job_engagement_closures c where c.application_id=new.application_id) then
    raise exception 'This Job Engagement is closed; no new Shift may be added.';
  end if;
  if exists(select 1 from public.work_assignment_creation_requests r
      where r.application_id=new.application_id and r.actor_id=new.created_by
        and r.scheduled_start=new.scheduled_start and r.scheduled_end=new.scheduled_end
        and r.cancelled_at is not null) then
    raise exception 'This Assignment Request was cancelled and cannot create a Shift.';
  end if;
  if exists (select 1 from public.work_assignments a
    where a.application_id=new.application_id and a.scheduled_start=new.scheduled_start
      and a.scheduled_end=new.scheduled_end and a.assignment_id<>new.assignment_id) then
    raise exception 'This application shift already exists.' using errcode='23505';
  end if;
  insert into public.work_assignment_shift_claims(application_id,scheduled_start,scheduled_end,assignment_id)
    values(new.application_id,new.scheduled_start,new.scheduled_end,new.assignment_id)
    on conflict do nothing;
  select assignment_id into v_claim from public.work_assignment_shift_claims
    where application_id=new.application_id and scheduled_start=new.scheduled_start and scheduled_end=new.scheduled_end;
  if v_claim is distinct from new.assignment_id then
    raise exception 'This application shift is already claimed.' using errcode='23505';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.lookup_work_assignment_request(p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_request public.work_assignment_creation_requests;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '28000'; END IF;
 SELECT * INTO v_request FROM public.work_assignment_creation_requests WHERE request_id = p_request_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF v_request.actor_id <> auth.uid() OR public.can_manage_company_jobs(v_request.company_id) IS NOT TRUE THEN
  RAISE EXCEPTION 'Request access denied.' USING ERRCODE = '42501';
 END IF;
 RETURN v_request.assignment_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_job_engagement_closure(p_application_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_app public.job_applications%rowtype; v_request_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required.' using errcode='28000'; end if;
  if p_reason is null or p_reason !~ '[^[:space:]]' or char_length(p_reason)>2000 then
    raise exception 'A closure request reason of 1 to 2000 characters is required.';
  end if;
  select * into v_app from public.job_applications a where a.application_id=p_application_id for update;
  if not found or v_app.status is distinct from 'hired' then raise exception 'A hired Job Application is required.'; end if;
  if v_app.applicant_id is distinct from auth.uid() then
    raise exception 'Only the Job Seeker on this Application may request closure.' using errcode='42501';
  end if;
  if exists(select 1 from public.job_engagement_closures c where c.application_id=p_application_id) then
    raise exception 'This Job Engagement is already closed.';
  end if;
  select r.request_id into v_request_id from public.job_engagement_closure_requests r
    where r.application_id=p_application_id and r.status='pending';
  if found then return v_request_id; end if;
  insert into public.job_engagement_closure_requests(application_id,worker_id,request_reason)
    values(p_application_id,auth.uid(),btrim(p_reason)) returning request_id into v_request_id;
  insert into public.job_engagement_closure_request_events(request_id,actor_id,action,reason)
    values(v_request_id,auth.uid(),'requested',btrim(p_reason));
  return v_request_id;
end
$function$

CREATE OR REPLACE FUNCTION public.request_more_work_evidence(p_assignment_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_assignment public.work_assignments%ROWTYPE;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF p_reason IS NULL
       OR char_length(btrim(p_reason)) NOT BETWEEN 1 AND 1000
    THEN
        RAISE EXCEPTION 'Reason must contain 1–1000 characters';
    END IF;

    SELECT *
    INTO v_assignment
    FROM public.work_assignments
    WHERE assignment_id = p_assignment_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Assignment not found';
    END IF;

    IF NOT public.can_manage_company_jobs(v_assignment.company_id) THEN
        RAISE EXCEPTION 'Not authorized to review this assignment';
    END IF;

    IF v_assignment.status <> 'awaiting_verification'
       OR v_assignment.verification_status <> 'pending_review'
    THEN
        RAISE EXCEPTION 'Assignment is not pending evidence review';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.work_evidence_submissions
        WHERE assignment_id = p_assignment_id
    ) THEN
        RAISE EXCEPTION 'No evidence submission exists';
    END IF;

    UPDATE public.work_assignments
    SET verification_status = 'more_evidence_required',
        updated_at = clock_timestamp()
    WHERE assignment_id = p_assignment_id;

    INSERT INTO public.work_verification_history (
        assignment_id,
        action,
        previous_status,
        new_status,
        performed_by,
        note
    )
    VALUES (
        p_assignment_id,
        'more_evidence_requested',
        'pending_review',
        'more_evidence_required',
        auth.uid(),
        btrim(p_reason)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.reserve_work_assignment_request(p_application_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_workplace_location text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_app record; v_request public.work_assignment_creation_requests;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '28000'; END IF;
 SELECT a.status, j.company_id INTO v_app FROM public.job_applications a
 JOIN public.job_postings j ON j.job_id = a.job_id
 WHERE a.application_id = p_application_id FOR UPDATE OF a, j;
 IF NOT FOUND THEN RAISE EXCEPTION 'Application unavailable.'; END IF;
 IF v_app.status <> 'hired' OR public.can_manage_company_jobs(v_app.company_id) IS NOT TRUE THEN
  RAISE EXCEPTION 'Employer access or hired eligibility denied.' USING ERRCODE = '42501';
 END IF;
 IF p_scheduled_start IS NULL OR p_scheduled_end IS NULL OR p_scheduled_end <= p_scheduled_start
 OR NOT isfinite(p_scheduled_start) OR NOT isfinite(p_scheduled_end)
 OR p_workplace_location IS NULL OR length(trim(p_workplace_location)) NOT BETWEEN 1 AND 500 THEN
  RAISE EXCEPTION 'Invalid shift payload.' USING ERRCODE = '22023';
 END IF;
 SELECT * INTO v_request FROM public.work_assignment_creation_requests
 WHERE actor_id = auth.uid() AND application_id = p_application_id
 AND scheduled_start = p_scheduled_start AND scheduled_end = p_scheduled_end;
 IF FOUND THEN
  IF v_request.workplace_location <> trim(p_workplace_location) THEN
   RAISE EXCEPTION 'Request payload cannot change.' USING ERRCODE = '22023';
  END IF;
  RETURN v_request.request_id;
 END IF;
 INSERT INTO public.work_assignment_creation_requests(actor_id, application_id, company_id,
 scheduled_start, scheduled_end, workplace_location)
 VALUES(auth.uid(), p_application_id, v_app.company_id, p_scheduled_start, p_scheduled_end, trim(p_workplace_location))
 RETURNING * INTO v_request;
 RETURN v_request.request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.respond_job_engagement_closure_request(p_request_id uuid, p_decision text, p_reason text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_app_id uuid; v_status text; v_closed_at timestamptz;
begin
  if auth.uid() is null then raise exception 'Authentication required.' using errcode='28000'; end if;
  if p_decision is null or p_decision not in ('close','decline') or p_reason is null or p_reason !~ '[^[:space:]]' or char_length(p_reason)>2000 then
    raise exception 'Choose close or decline and provide a reason of 1 to 2000 characters.';
  end if;
  select r.application_id into v_app_id from public.job_engagement_closure_requests r where r.request_id=p_request_id;
  if not found then raise exception 'Closure Request not found.'; end if;
  perform 1 from public.job_applications a where a.application_id=v_app_id for update;
  if not found then raise exception 'Job Application not found.'; end if;
  select r.status into v_status from public.job_engagement_closure_requests r
    where r.request_id=p_request_id for update;
  if not found or v_status is distinct from 'pending' then raise exception 'Closure Request is no longer pending.'; end if;
  if p_decision='close' then
    v_closed_at:=private.record_job_engagement_closure(v_app_id,auth.uid(),p_reason);
    return v_closed_at;
  end if;
  update public.job_engagement_closure_requests set status='declined',processed_by=auth.uid(),
    processed_at=pg_catalog.clock_timestamp(),response_reason=btrim(p_reason)
    where request_id=p_request_id;
  insert into public.job_engagement_closure_request_events(request_id,actor_id,action,reason)
    values(p_request_id,auth.uid(),'declined',btrim(p_reason));
  return null;
end
$function$

CREATE OR REPLACE FUNCTION public.submit_work_evidence(p_assignment_id uuid, p_description text, p_storage_paths text[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_assignment public.work_assignments%ROWTYPE;
    v_round integer;
    v_path text;
    v_file_count integer;
    v_existing_count integer;
    v_object_count integer;
    v_mime_type text;
    v_file_name text;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF p_description IS NULL
       OR char_length(btrim(p_description)) NOT BETWEEN 1 AND 2000
    THEN
        RAISE EXCEPTION 'Description must contain 1–2000 characters';
    END IF;

    v_file_count := coalesce(array_length(p_storage_paths, 1), 0);

    IF v_file_count NOT BETWEEN 1 AND 5 THEN
        RAISE EXCEPTION 'Submit between 1 and 5 evidence files';
    END IF;

    SELECT *
    INTO v_assignment
    FROM public.work_assignments
    WHERE assignment_id = p_assignment_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Assignment not found';
    END IF;

    IF v_assignment.worker_id <> auth.uid() THEN
        RAISE EXCEPTION 'Not authorized for this assignment';
    END IF;
    IF NOT EXISTS (
    SELECT 1
    FROM public.users u
    WHERE u.user_id = auth.uid()
      AND u.role = 'job_seeker'::public.user_role
      AND u.status = 'active'::public.account_status
) THEN
    RAISE EXCEPTION
        'Only active job seekers may submit work evidence';
END IF;

    IF v_assignment.status <> 'awaiting_verification'
       OR v_assignment.verification_status NOT IN (
           'not_submitted',
           'more_evidence_required'
       )
    THEN
        RAISE EXCEPTION 'Evidence submission is not currently allowed';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.work_attendance
        WHERE assignment_id = p_assignment_id
          AND check_in_at IS NOT NULL
          AND check_out_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'Check-in and check-out are required';
    END IF;

    -- Do not allow the same path twice within one submission.
    SELECT count(DISTINCT path)
    INTO v_existing_count
    FROM unnest(p_storage_paths) AS paths(path);

    IF v_existing_count <> v_file_count THEN
        RAISE EXCEPTION 'Duplicate or invalid evidence paths';
    END IF;

    SELECT coalesce(max(submission_round), 0) + 1
    INTO v_round
    FROM public.work_evidence_submissions
    WHERE assignment_id = p_assignment_id;

    IF v_assignment.verification_status = 'not_submitted'
       AND v_round <> 1 THEN
        RAISE EXCEPTION 'Invalid first submission';
    END IF;

    IF v_assignment.verification_status = 'more_evidence_required'
       AND v_round = 1 THEN
        RAISE EXCEPTION 'No previous submission to supplement';
    END IF;

    -- Validate each file against the private Storage bucket.
    FOREACH v_path IN ARRAY p_storage_paths LOOP

    IF v_path IS NULL
    OR v_path !~ (
        '^'
        || p_assignment_id::text
        || '/[A-Za-z0-9][A-Za-z0-9._-]{0,199}\.(jpg|jpeg|png|webp|pdf)$'
    )
    THEN
        RAISE EXCEPTION
            'Invalid evidence file path or unsupported filename';
    END IF;

        -- Confirm the object exists, belongs to this worker,
        -- and is within the 10 MB file-size limit.

        SELECT count(*), max(o.metadata ->> 'mimetype')
        INTO v_object_count, v_mime_type
        FROM storage.objects o
        WHERE o.bucket_id = 'work-evidence'
            AND o.name = v_path
            AND o.owner_id = auth.uid()::text
            AND (o.metadata ->> 'size') ~ '^[0-9]+$'
            AND (o.metadata ->> 'size')::bigint
                BETWEEN 1 AND 10485760;

        IF v_object_count <> 1 THEN
            RAISE EXCEPTION 'Evidence file not found in private storage';
        END IF;

        IF v_mime_type NOT IN (
            'image/jpeg',
            'image/png',
            'image/webp',
            'application/pdf'
        ) THEN
            RAISE EXCEPTION 'Unsupported evidence file type';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM public.work_evidence e
            WHERE e.storage_path = v_path
        ) THEN
            RAISE EXCEPTION 'Evidence file has already been submitted';
        END IF;

        v_file_name := split_part(v_path, '/', 2);

        INSERT INTO public.work_evidence (
            assignment_id,
            submitted_by,
            submission_round,
            description,
            storage_path,
            file_name,
            mime_type
        )
        VALUES (
            p_assignment_id,
            auth.uid(),
            v_round,
            btrim(p_description),
            v_path,
            v_file_name,
            v_mime_type
        );
    END LOOP;

    INSERT INTO public.work_evidence_submissions (
        assignment_id,
        submission_round,
        submitted_by,
        description,
        file_count
    )
    VALUES (
        p_assignment_id,
        v_round,
        auth.uid(),
        btrim(p_description),
        v_file_count
    );

    INSERT INTO public.work_verification_history (
        assignment_id,
        action,
        previous_status,
        new_status,
        performed_by,
        note
    )
    VALUES (
        p_assignment_id,
        CASE
            WHEN v_round = 1 THEN 'evidence_submitted'
            ELSE 'evidence_resubmitted'
        END,
        v_assignment.verification_status,
        'pending_review',
        auth.uid(),
        NULL
    );

    UPDATE public.work_assignments
    SET verification_status = 'pending_review',
        updated_at = clock_timestamp()
    WHERE assignment_id = p_assignment_id;

    RETURN v_round;
END;
$function$
